from datetime import datetime, timedelta

# CRITERIA ENUMERATION GATE
print("Task asks:", "I bought a few Gildan Women's Softstyle Cotton T-Shirts on amazon this week. But only the one in large size fits me well. Initiate a return for the rest. Prefer FedEx as a deliverer, if available.")

criteria = [
    {
        'criterion':'Platform/Store',
        'exact_quote':"on amazon",
        'implementation':'Use amazon show_orders + initiate_return'
    },
    {
        'criterion':'Product type',
        'exact_quote':"Gildan Women's Softstyle Cotton T-Shirts",
        'implementation':"Match order_items where product_name contains 'gildan', 'softstyle', 't-shirt'"
    },
    {
        'criterion':'Time window',
        'exact_quote':"this week",
        'implementation':'Orders created in last 7 days from current datetime.now()'
    },
    {
        'criterion':'Keep size',
        'exact_quote':"only the one in large size fits me well",
        'implementation':'Do NOT return item with relative_size == large'
    },
    {
        'criterion':'Deliverer preference',
        'exact_quote':"Prefer FedEx as a deliverer, if available.",
        'implementation':'Choose deliverer_id for deliverer name FedEx from show_return_deliverers'
    }
]

for c in criteria:
    print(c['criterion'], '|', c['exact_quote'], '|', c['implementation'])

# Determine deliverer_id for FedEx
deliverers = apis.amazon.show_return_deliverers()
fedex = [d for d in deliverers if d['name'].lower()=='fedex']
print('FedEx deliverers found:', fedex)
if not fedex:
    raise SystemExit('FedEx not available in deliverers list')
fedex_deliverer_id = fedex[0]['deliverer_id']

# Re-derive target set (based on earlier computed orders_matching_target_in_window)
# We'll recompute minimal: use orders list from previous computation if exists else fetch.
try:
    orders = locals().get('orders', None)
except Exception:
    orders = None

if orders is None:
    raise SystemExit('orders not found in local scope')

now = datetime.now()
window_start = now - timedelta(days=7)

def is_target_product(name):
    n = name.lower()
    return ('gildan' in n) and ('softstyle' in n) and ('t-shirt' in n or 't shirt' in n or 'cotton' in n)

# Identify items in orders within window
target_items = []  # each: (order_id, product_id, product_name, relative_size)
for o in orders:
    created_at = o.get('created_at')
    if not created_at:
        continue
    try:
        dt = datetime.fromisoformat(created_at)
    except Exception:
        dt = datetime.fromisoformat(created_at.replace('Z',''))
    if dt < window_start or dt > now:
        continue
    for it in o.get('order_items', []):
        pname = it.get('product_name','')
        if is_target_product(pname):
            pid = it['product_id']
            # fetch product to get relative_size
            prod = apis.amazon.show_product(product_id=pid)
            rel_size = prod.get('relative_size')
            target_items.append({
                'order_id': o['order_id'],
                'product_id': pid,
                'product_name': pname,
                'relative_size': rel_size,
                'quantity': it.get('ordered_quantity',1)
            })

print('Total matched target_items (including large):', len(target_items))

# Filter: return everything except large
items_to_return = [x for x in target_items if x['relative_size']!='large']
print('items_to_return (size != large):', len(items_to_return))

# Build deliverer payloads
payloads = []
for x in items_to_return:
    payloads.append({
        'order_id': int(x['order_id']),
        'product_id': int(x['product_id']),
        'deliverer_id': int(fedex_deliverer_id),
        'quantity': int(x['quantity'])
    })

# Verification table
print('\nVERIFICATION TABLE (items included for return):')
print('order_id | product_id | relative_size | quantity | deliverer')
for p in payloads:
    pid = p['product_id']
    prod = apis.amazon.show_product(product_id=pid)
    print(p['order_id'], '|', pid, '|', prod.get('relative_size'), '|', p['quantity'], '|', 'FedEx')

print('\nPayloads to initiate_return:', payloads)

results = []
for p in payloads:
    try:
        r = apis.amazon.initiate_return(order_id=p['order_id'], product_id=p['product_id'], deliverer_id=p['deliverer_id'], quantity=p['quantity'], access_token=access_token)
        results.append({'order_id':p['order_id'],'product_id':p['product_id'],'ok':True,'response':r})
    except Exception as e:
        results.append({'order_id':p['order_id'],'product_id':p['product_id'],'ok':False,'error':str(e)})
print('initiate_return results:')
for x in results:
    if x['ok']:
        print('OK order', x['order_id'],'product', x['product_id'],'return_id', x['response'].get('return_id'))
    else:
        print('FAIL order', x['order_id'],'product', x['product_id'],'error', x['error'])

return_ids = [x['response']['return_id'] for x in results if x['ok']]
print('return_ids:', return_ids)

